        vec2 dvec_ab = vec_b - vec_a;  // Displacement vector from vec_a to vec_b
        vec2 vproj_ap_ab = dvec_ab * vproj_scalar(dvec_ap, dvec_ab);  // Standard linear algebra vector projection!
