        #ifdef HAS_ORM_MAP
            color = mix(color, color * ao, uOcclusionStrength);
        #endif

        #ifdef HAS_EMISSIVEMAP
            vec3 emissive = SRGBtoLINEAR(texture(uEmissiveSampler, vUv * uUvScale)).rgb * uEmissiveFactor;
