        #ifdef HAS_FOG
            float fogDistance = length(vWorldPosition);
            // float fogAmount = 1. - exp2(-uFogDensity * uFogDensity * fogDistance * fogDistance * LOG2);
            float fogAmount = smoothstep(uFogNear, uFogFar, fogDistance);
