        in vec3 position1;
        in vec3 normal1;
        uniform float uActivePoseMix;
    #endif
    #ifdef HAS_TANGENTS
        in vec3 tangents;
    #endif

    #ifdef HAS_UV
        in vec2 uv;
    #endif

    uniform mat4 modelMatrix;
    uniform mat4 modelViewMatrix;
    uniform mat3 normalMatrix;
    uniform mat4 projectionMatrix;

    uniform float uTime;

    out vec3 vPosition;
    out vec3 vWorldPosition;
    out vec2 vUv;

    #ifdef HAS_NORMALS
        #ifdef HAS_TANGENTS
            out mat3 vTBN;
        #else
            out vec3 vNormal;
        #endif
    #endif

